// spec: .qa/e2e/specs/match-mutual.md 1.1 · кейс .qa/tests/match-mutual/MATCH-01.md
import { test, expect } from '../../fixtures';
import { captureApi, rpc, myMatches, rowsWith, matchIdOf } from '../_shared/api';
import { saveSession } from '../_shared/session';

const MATCH = '2651ee46'; // мэтч free↔user4 (тестовые данные, не удалять)

test.describe('Взаимный матч (сервер)', () => {
  test('Повторный like по сматченной паре не создаёт второй мэтч; мэтч виден обеим сторонам @iphone @data (#b76c3b)', async ({ asUser }) => {
    const free = await asUser('free');
    const user4 = await asUser('user4');
    await free.setViewportSize({ width: 390, height: 844 });
    await user4.setViewportSize({ width: 390, height: 844 });
    try {
      const a = await captureApi(free);
      const b = await captureApi(user4);

      // Повторный like free → user4 (AC 1, 3): принят, второй мэтч не создаётся (AC 5).
      const res = await rpc(a, 'swipe', { p_target: b.userId, p_kind: 'like' });
      expect(res.ok(), `swipe: ${res.status()} ${await res.text()}`).toBeTruthy();
      const body = await res.json().catch(() => ({}));
      const mid = (Array.isArray(body) ? body[0] : body)?.match_id;
      if (mid) expect(String(mid).startsWith(MATCH)).toBeTruthy();

      // Ровно одна запись мэтча у каждой стороны.
      const mineA = rowsWith(await myMatches(a), b.userId);
      expect(mineA).toHaveLength(1);
      expect(matchIdOf(mineA[0]).startsWith(MATCH)).toBeTruthy();
      const mineB = rowsWith(await myMatches(b), a.userId);
      expect(mineB).toHaveLength(1);
      expect(matchIdOf(mineB[0])).toBe(matchIdOf(mineA[0]));
    } finally {
      await saveSession(free, 'free');
      await saveSession(user4, 'user4');
    }
  });
});
